let S, sets, pts;

function setup() {
  createCanvas(windowWidth, windowHeight);
	background(2, 2, 8);
	describe("visualization of union of 2 circles with random points on dark background");

  noFill();
	stroke("silver");
  strokeWeight(2);
	S = max(width, height);
	const d = max(width, height);
	sets = [];
	sets[0] = {x: 0, y: 0, r: d * 0.25, clr: "azure"};
	sets[1] = {x: 0, y: 0, r: d * 0.25, clr: "silver"};
	if (width > height) {
		sets[0].x = width/3;
		sets[0].y = height/2;
		sets[1].x = width - width/3;
		sets[1].y = height/2;
	} else {
		sets[0].x = width/2
		sets[0].y = height/3;
		sets[1].x = width/2;
		sets[1].y = height - height/3;
	}

	pts = []

  loop();
}

function draw() {
	if (frameCount % 1000 === 0) {
		background("rgb(2, 2, 8)");
		pts = [];
	}

	addPoint();

	noFill()
	strokeWeight(2);
	for (let set of sets) {
		stroke(set.clr);
		circle(set.x, set.y, set.r*2)
	}

	// deactivated, wil be drawn in addPoint; activate in using background() in draw()
	/*
	for (const p of pts) {
		stroke(p.clr);
		strokeWeight(p.sw)
		point(p.x, p.y);
	}
	*/

}

function addPoint() {
	const x = randomGaussian(width/2, width/4); // random(width);
	const y = randomGaussian(height/2, height/4); // random(height);
	const sw = map(dist(x, y, width/2, height/2), 0, (width+height)/2, 10, 0);
	const isA = dist(x, y, sets[0].x, sets[0].y) < sets[0].r;
	const isB = dist(x, y, sets[1].x, sets[1].y) < sets[1].r;
	let clr = (isA && isB) ? "cyan" : (isA || isB) ? "purple" : "gray";
	pts.push({x, y, sw, clr});

	stroke(clr);
	strokeWeight(sw)
	point(x, y);
}

function noisom(v1, v2) {
	if (v1>v2) [v1, v2] = [v2, v1];
	const n = noise(v1, v2, frameCount/123);
	return v1+n*(v2-v1);
}

function mouseClicked() {
  if (mouseButton === LEFT) setup();
}
